-- ## Core Transactions
--
-- Foundation transaction data capturing all monetary movements across accounts.
-- Includes the primary transaction ledger, transaction type reference data,
-- and reversal/correction records. This dataset serves as the authoritative
-- source for all account-level transaction activity.
--
-- Layer:            bronze
-- Classification:   Restricted
-- Regulatory scope: GLBA, GDPR, CCPA, Regulation E, BSA

/** Primary transaction ledger recording all account monetary movements.
    Grain: one row per transaction_id. */
CREATE TABLE Transaction (
  /** Unique identifier for the transaction */
  transaction_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Transaction type code reference */
  transaction_type_code STRING,
  /** Transaction category: DEBIT, CREDIT */
  transaction_category STRING,
  /** Transaction amount in cents @npi @confidential */
  amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Transaction status: PENDING, POSTED, REVERSED, RETURNED */
  transaction_status STRING,
  /** Date transaction was posted to account */
  posted_date DATE,
  /** Date and time transaction occurred */
  transaction_at TIMESTAMP,
  /** Effective date for interest calculation */
  effective_date DATE,
  /** Transaction description @pii */
  description STRING,
  /** Memo or reference text @pii */
  memo STRING,
  /** Running balance after transaction in cents @npi @confidential */
  running_balance_cents BIGINT,
  /** Channel: BRANCH, ATM, ONLINE, MOBILE, ACH, WIRE, CHECK, POS, INTERNAL */
  channel STRING,
  /** Reference number for external transactions */
  external_reference STRING,
  /** Trace number for ACH transactions */
  trace_number STRING,
  /** Check number if applicable */
  check_number STRING,
  /** Branch ID where transaction occurred */
  branch_id STRING,
  /** Terminal or device ID */
  terminal_id STRING,
  /** Employee ID if branch transaction @pii */
  teller_id STRING,
  /** Counterparty account reference @npi */
  counterparty_account_id STRING,
  /** Counterparty name @pii */
  counterparty_name STRING,
  /** Whether transaction has been reconciled */
  is_reconciled BOOLEAN,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Transaction type reference data defining transaction classifications.
    Grain: one row per transaction_type_code. */
CREATE TABLE Transaction_Type (
  /** Unique transaction type code */
  transaction_type_code STRING,
  /** Transaction type name */
  transaction_type_name STRING,
  /** Transaction type description */
  description STRING,
  /** Category: DEBIT, CREDIT */
  category STRING,
  /** Subcategory for reporting */
  subcategory STRING,
  /** Whether this type is customer-initiated */
  is_customer_initiated BOOLEAN,
  /** Whether this type affects available balance */
  affects_available_balance BOOLEAN,
  /** Whether this type is fee-related */
  is_fee BOOLEAN,
  /** Whether this type is interest-related */
  is_interest BOOLEAN,
  /** GL account code for posting */
  gl_account_code STRING,
  /** Whether type is currently active */
  is_active BOOLEAN,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Transaction reversals and corrections linking to original transactions.
    Grain: one row per reversal_id. */
CREATE TABLE Transaction_Reversal (
  /** Unique identifier for the reversal */
  reversal_id STRING,
  /** Reference to original transaction being reversed */
  original_transaction_id STRING,
  /** Reference to the reversing transaction */
  reversing_transaction_id STRING,
  /** Reversal type: FULL, PARTIAL, CORRECTION */
  reversal_type STRING,
  /** Amount reversed in cents @npi @confidential */
  reversal_amount_cents BIGINT,
  /** Reason code for reversal */
  reason_code STRING,
  /** Reason description @confidential */
  reason_description STRING,
  /** Date and time reversal was initiated */
  reversed_at TIMESTAMP,
  /** Date reversal was posted */
  posted_date DATE,
  /** Employee or system initiating reversal */
  reversed_by STRING,
  /** Supervisor approval if required @pii */
  approved_by STRING,
  /** Channel through which reversal was made */
  channel STRING,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

-- ## Wire and ACH Transactions
--
-- Electronic funds transfer data including ACH transactions, domestic and
-- international wire transfers, and payment returns. Supports regulatory
-- reporting requirements and fraud monitoring for high-value transfers.
--
-- Layer:            bronze
-- Classification:   Restricted
-- Regulatory scope: GLBA, GDPR, CCPA, BSA, OFAC, Regulation E

/** ACH transaction records for direct deposits, bill payments, and transfers.
    Grain: one row per ach_transaction_id. */
CREATE TABLE Ach_Transaction (
  /** Unique identifier for the ACH transaction */
  ach_transaction_id STRING,
  /** Reference to posted transaction */
  transaction_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Direction: INBOUND, OUTBOUND */
  direction STRING,
  /** ACH transaction type: CREDIT, DEBIT */
  ach_type STRING,
  /** SEC code: PPD, CCD, WEB, TEL, etc. */
  sec_code STRING,
  /** Transaction amount in cents @npi @confidential */
  amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Transaction status: ORIGINATED, PENDING, POSTED, RETURNED, REJECTED */
  transaction_status STRING,
  /** Originating DFI routing number */
  odfi_routing_number STRING,
  /** Originating DFI name */
  odfi_name STRING,
  /** Receiving DFI routing number */
  rdfi_routing_number STRING,
  /** Receiving DFI name */
  rdfi_name STRING,
  /** Company/batch ID */
  company_id STRING,
  /** Company name @pii */
  company_name STRING,
  /** Company entry description */
  entry_description STRING,
  /** Individual/account name @pii @encrypt */
  individual_name STRING,
  /** Individual identification number @pii @tokenize */
  individual_id STRING,
  /** Trace number */
  trace_number STRING,
  /** Addenda records (JSON) @pii */
  addenda STRING,
  /** Effective entry date */
  effective_date DATE,
  /** Settlement date */
  settlement_date DATE,
  /** Date and time transaction was processed */
  processed_at TIMESTAMP,
  /** Whether transaction is same-day ACH */
  is_same_day BOOLEAN,
  /** Batch reference number */
  batch_number STRING,
  /** File ID from ACH file */
  file_id STRING,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Wire transfer records for domestic and international transfers.
    Grain: one row per wire_transfer_id. */
CREATE TABLE Wire_Transfer (
  /** Unique identifier for the wire transfer */
  wire_transfer_id STRING,
  /** Reference to posted transaction */
  transaction_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Reference to customer @pii */
  customer_id STRING,
  /** Direction: INBOUND, OUTBOUND */
  direction STRING,
  /** Wire type: DOMESTIC, INTERNATIONAL */
  wire_type STRING,
  /** Transfer amount in cents @npi @confidential */
  amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Fee amount in cents */
  fee_cents BIGINT,
  /** Total amount debited/credited in cents @npi @confidential */
  total_amount_cents BIGINT,
  /** Wire status: INITIATED, PENDING, SENT, RECEIVED, COMPLETED, RETURNED, CANCELLED */
  wire_status STRING,
  /** Originator name @pii @encrypt */
  originator_name STRING,
  /** Originator address @pii @encrypt */
  originator_address STRING,
  /** Originator account number @npi @mask */
  originator_account STRING,
  /** Originator bank name */
  originator_bank_name STRING,
  /** Originator bank routing/SWIFT @bsa */
  originator_bank_id STRING,
  /** Beneficiary name @pii @encrypt */
  beneficiary_name STRING,
  /** Beneficiary address @pii @encrypt */
  beneficiary_address STRING,
  /** Beneficiary account number @npi @mask */
  beneficiary_account STRING,
  /** Beneficiary bank name */
  beneficiary_bank_name STRING,
  /** Beneficiary bank routing/SWIFT @bsa */
  beneficiary_bank_id STRING,
  /** Beneficiary bank country */
  beneficiary_country STRING,
  /** Intermediary bank name (for international) */
  intermediary_bank_name STRING,
  /** Intermediary bank SWIFT */
  intermediary_bank_id STRING,
  /** Purpose of wire transfer @confidential */
  purpose STRING,
  /** Reference for beneficiary */
  reference_for_beneficiary STRING,
  /** OMAD/IMAD reference number */
  fed_reference STRING,
  /** SWIFT reference (for international) */
  swift_reference STRING,
  /** OFAC screening result: CLEAR, HOLD, BLOCKED */
  ofac_status STRING,
  /** Date and time wire was initiated */
  initiated_at TIMESTAMP,
  /** Date and time wire was sent */
  sent_at TIMESTAMP,
  /** Date and time wire was completed */
  completed_at TIMESTAMP,
  /** Employee or system initiating wire @pii */
  initiated_by STRING,
  /** Approval status: PENDING, APPROVED, REJECTED */
  approval_status STRING,
  /** Employee approving wire @pii */
  approved_by STRING,
  /** Date and time of approval */
  approved_at TIMESTAMP,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Payment return records for ACH returns and wire rejects.
    Grain: one row per return_id. */
CREATE TABLE Payment_Return (
  /** Unique identifier for the return */
  return_id STRING,
  /** Reference to original ACH transaction */
  ach_transaction_id STRING,
  /** Reference to original wire transfer */
  wire_transfer_id STRING,
  /** Reference to original transaction */
  original_transaction_id STRING,
  /** Reference to return transaction */
  return_transaction_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Return type: ACH_RETURN, ACH_NOC, WIRE_RETURN, WIRE_REJECT */
  return_type STRING,
  /** Return amount in cents @npi @confidential */
  return_amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Return status: PENDING, PROCESSED, DISPUTED */
  return_status STRING,
  /** Return reason code (R01-R85 for ACH) */
  return_reason_code STRING,
  /** Return reason description @confidential */
  return_reason_description STRING,
  /** Original effective date */
  original_effective_date DATE,
  /** Return effective date */
  return_effective_date DATE,
  /** Date and time return was processed */
  processed_at TIMESTAMP,
  /** Trace number of original transaction */
  original_trace_number STRING,
  /** Trace number of return */
  return_trace_number STRING,
  /** Addenda information (JSON) */
  addenda STRING,
  /** Whether return was dishonored */
  is_dishonored BOOLEAN,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

-- ## Card Transactions
--
-- Debit and prepaid card transaction data including real-time authorizations,
-- settlements, and chargeback processing. Captures the full lifecycle of
-- card-based payments from authorization through final settlement and any
-- disputes that may arise.
--
-- Layer:            bronze
-- Classification:   Restricted
-- Regulatory scope: GLBA, GDPR, CCPA, Regulation E, PCI-DSS

/** Real-time card authorization requests and responses.
    Grain: one row per authorization_id. */
CREATE TABLE Card_Authorization (
  /** Unique identifier for the authorization */
  authorization_id STRING,
  /** Reference to card used @pci @tokenize */
  card_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Authorization amount in cents @npi @confidential */
  authorization_amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Merchant amount if different currency in cents */
  merchant_amount_cents BIGINT,
  /** Merchant currency code */
  merchant_currency_code STRING,
  /** Exchange rate applied */
  exchange_rate DECIMAL(12, 6),
  /** Authorization status: APPROVED, DECLINED, PENDING, EXPIRED, REVERSED */
  authorization_status STRING,
  /** Decline reason code if declined */
  decline_reason_code STRING,
  /** Date and time of authorization */
  authorized_at TIMESTAMP,
  /** Authorization expiration timestamp */
  expires_at TIMESTAMP,
  /** Merchant name @pii */
  merchant_name STRING,
  /** Merchant ID */
  merchant_id STRING,
  /** Merchant Category Code */
  mcc_code STRING,
  /** Merchant city @pii */
  merchant_city STRING,
  /** Merchant state or province */
  merchant_state STRING,
  /** Merchant country code */
  merchant_country STRING,
  /** Transaction type: PURCHASE, CASH_ADVANCE, REFUND, BALANCE_INQUIRY */
  transaction_type STRING,
  /** Entry mode: CHIP, SWIPE, CONTACTLESS, MANUAL, ECOMMERCE, RECURRING */
  entry_mode STRING,
  /** Whether PIN was used */
  pin_used BOOLEAN,
  /** Whether card was present */
  card_present BOOLEAN,
  /** Network: VISA, MASTERCARD, DISCOVER, AMEX */
  network STRING,
  /** Network reference ID */
  network_reference_id STRING,
  /** Retrieval reference number */
  rrn STRING,
  /** Authorization code from network */
  authorization_code STRING,
  /** CVV verification result */
  cvv_result STRING,
  /** AVS verification result */
  avs_result STRING,
  /** 3D Secure result if applicable */
  three_ds_result STRING,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Card transaction settlements from payment networks.
    Grain: one row per settlement_id. */
CREATE TABLE Card_Settlement (
  /** Unique identifier for the settlement */
  settlement_id STRING,
  /** Reference to original authorization */
  authorization_id STRING,
  /** Reference to posted transaction */
  transaction_id STRING,
  /** Reference to card @pci @tokenize */
  card_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Settlement amount in cents @npi @confidential */
  settlement_amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Original authorization amount in cents */
  authorization_amount_cents BIGINT,
  /** Difference between settlement and authorization in cents */
  variance_cents BIGINT,
  /** Settlement status: SETTLED, PENDING, REJECTED */
  settlement_status STRING,
  /** Date and time of settlement */
  settled_at TIMESTAMP,
  /** Settlement date from network */
  network_settlement_date DATE,
  /** Merchant name @pii */
  merchant_name STRING,
  /** Merchant ID */
  merchant_id STRING,
  /** Merchant Category Code */
  mcc_code STRING,
  /** Network: VISA, MASTERCARD, DISCOVER, AMEX */
  network STRING,
  /** Network reference ID */
  network_reference_id STRING,
  /** Interchange fee in cents @confidential */
  interchange_fee_cents BIGINT,
  /** Network assessment fee in cents @confidential */
  assessment_fee_cents BIGINT,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Card dispute and chargeback records.
    Grain: one row per chargeback_id. */
CREATE TABLE Card_Chargeback (
  /** Unique identifier for the chargeback */
  chargeback_id STRING,
  /** Reference to original transaction */
  transaction_id STRING,
  /** Reference to settlement */
  settlement_id STRING,
  /** Reference to card @pci @tokenize */
  card_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Reference to customer @pii */
  customer_id STRING,
  /** Chargeback amount in cents @npi @confidential */
  chargeback_amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Chargeback status: INITIATED, PENDING, WON, LOST, EXPIRED */
  chargeback_status STRING,
  /** Reason code per network rules */
  reason_code STRING,
  /** Reason description @confidential */
  reason_description STRING,
  /** Category: FRAUD, CONSUMER_DISPUTE, PROCESSING_ERROR, AUTHORIZATION */
  chargeback_category STRING,
  /** Date chargeback was initiated */
  initiated_at TIMESTAMP,
  /** Response deadline */
  response_due_date DATE,
  /** Date chargeback was resolved */
  resolved_at TIMESTAMP,
  /** Resolution outcome: MERCHANT_WIN, CUSTOMER_WIN, SPLIT */
  resolution_outcome STRING,
  /** Amount recovered from merchant in cents */
  recovery_amount_cents BIGINT,
  /** Merchant name @pii */
  merchant_name STRING,
  /** Merchant ID */
  merchant_id STRING,
  /** Network handling the dispute */
  network STRING,
  /** Network case number */
  network_case_number STRING,
  /** Whether provisional credit was issued */
  provisional_credit_issued BOOLEAN,
  /** Date provisional credit was issued */
  provisional_credit_date DATE,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

/** Merchant Category Code reference data for transaction classification.
    Grain: one row per mcc_code. */
CREATE TABLE Mcc_Reference (
  /** Merchant Category Code */
  mcc_code STRING,
  /** MCC description */
  mcc_description STRING,
  /** Category grouping */
  category STRING,
  /** Subcategory */
  subcategory STRING,
  /** Whether MCC is considered high-risk */
  is_high_risk BOOLEAN,
  /** Whether MCC may indicate cash-like transaction */
  is_cash_equivalent BOOLEAN,
  /** Whether MCC is restricted for certain card programs */
  is_restricted BOOLEAN,
  /** Default tax category */
  tax_category STRING,
  /** Source system identifier */
  source_system STRING,
  /** Timestamp when record was ingested into the data platform */
  ingested_at TIMESTAMP,
  /** Timestamp when record was last updated in source system */
  source_updated_at TIMESTAMP
);

-- ## Enriched Transactions
--
-- Silver-layer transaction data combining and enriching information from
-- multiple bronze sources to create unified transaction views with merchant
-- enrichment, categorization, and recurring payment detection.
--
-- Layer:            silver
-- Classification:   Restricted
-- Regulatory scope: GLBA, GDPR, CCPA
-- Upstream:         core_transactions.sqrl, card_transactions.sqrl, wire_ach_transactions.sqrl

/** Unified transaction view combining all transaction types with standardized attributes.
    Grain: one row per transaction_id. */
CREATE TABLE Unified_Transaction (
  /** Unique identifier for the transaction */
  transaction_id STRING,
  /** Reference to account @npi */
  account_id STRING,
  /** Reference to customer @pii */
  customer_id STRING,
  /** Transaction source: CORE, CARD, ACH, WIRE */
  transaction_source STRING,
  /** Original source system transaction ID */
  source_transaction_id STRING,
  /** Standardized transaction type */
  transaction_type STRING,
  /** Transaction category: DEBIT, CREDIT */
  debit_credit STRING,
  /** Transaction amount in cents @npi @confidential */
  amount_cents BIGINT,
  /** Currency code (ISO 4217) */
  currency_code STRING,
  /** Transaction status: PENDING, POSTED, REVERSED, RETURNED */
  transaction_status STRING,
  /** Date and time transaction occurred */
  transaction_at TIMESTAMP,
  /** Date transaction was posted */
  posted_date DATE,
  /** Original description @pii */
  original_description STRING,
  /** Cleaned/standardized description @pii */
  clean_description STRING,
  /** Transaction channel: BRANCH, ATM, ONLINE, MOBILE, ACH, WIRE, POS, CHECK */
  channel STRING,
